#!/usr/bin/env perl
use strict;
use warnings;
use Test::More;
use File::Spec;
use FindBin;
use JSON::PP ();

use lib File::Spec->catdir($FindBin::Bin, '..', 'perl');
use FSM::Adapter::ISF;
use FSM::Scheduler::ISF;

sub entry_by_name {
    my ($items, $name) = @_;
    my ($entry) = grep { $_->{name} eq $name } @$items;
    return $entry;
}

subtest 'schedule JSON reports assigned counters with inferred widths' => sub {
    my $isf_file = File::Spec->catfile($FindBin::Bin, '..', 'isf', 'apb_requester.isf');
    my $actor    = FSM::Adapter::ISF->new()->parse_file($isf_file);
    my $json     = FSM::Scheduler::ISF->new()->report($actor);
    my $report   = JSON::PP->new->decode($json);
    my $storage  = $report->{inferred_storage};

    my @watchdogs = grep { $_->{name} eq 'apb_transfer_wd' } @$storage;
    is(scalar(@watchdogs), 1, 'watchdog counter appears once');
    is($watchdogs[0]{kind},  'counter', 'watchdog storage is classified as a counter');
    is($watchdogs[0]{role},  'watchdog_counter', 'watchdog storage reports its scheduler role');
    is($watchdogs[0]{width}, 17,        'watchdog storage keeps the inferred width');

    my $latency_counter = entry_by_name($storage, 'apb_transfer_cc');
    is($latency_counter->{kind},  'counter', 'latency storage is classified as a counter');
    is($latency_counter->{role},  'latency_counter', 'latency storage reports its scheduler role');
    is($latency_counter->{width}, 5,         'latency storage keeps the max-bound inferred width');

    my $last_error = entry_by_name($storage, 'last_error');
    is($last_error->{kind}, 'register', 'ordinary flopped output remains register storage');
    is($last_error->{width}, 1, 'ordinary register storage reports its known width');
};

subtest 'generated named-drive requests retain counter metadata' => sub {
    my $path = File::Spec->catfile($FindBin::Bin, '..', 'isf', 'spawn_parent.isf');
    my $actor = FSM::Adapter::ISF->new()->parse_file($path);
    my $report = JSON::PP->new->decode(FSM::Scheduler::ISF->new()->report($actor));
    my @instances = @{$report->{generated_composition}{instances} || []};

    is_deeply([map { $_->{instance} } @instances], [qw(w0 w1 w2)],
        'fixture exposes each generated child instance');
    for my $instance (@instances) {
        my $label = $instance->{instance};
        my ($handoff) = grep { $_->{drive} eq 'rdata' }
            @{$instance->{drive_handoffs} || []};
        ok($handoff, "$label exposes its named-drive handoff");
        next unless $handoff;

        # Follow the public binding instead of assuming an allocated signal name.
        my $name = $handoff->{request}{parent_port};
        ok(defined($name) && length($name), "$label names its parent request signal");
        next unless defined($name) && length($name);
        my $entry = entry_by_name($report->{inferred_storage}, $name);
        ok($entry, "$label request appears in inferred storage");
        next unless $entry;

        is($entry->{kind}, 'counter', "$label request retains its counter-table kind");
        is($entry->{role}, 'drive_request', "$label request reports its drive role");
        is($entry->{width}, 1, "$label request retains its one-bit counter-table width");
    }
};

done_testing();

source_texts.t/1128-isf-public-multifile-schedule-rep:
#!/usr/bin/env perl
use strict;
use warnings;
use Test::More;
use File::Spec;
use FindBin;
use IPC::Cmd qw(run);
use JSON::PP ();

use lib File::Spec->catdir($FindBin::Bin, '..', 'perl');

use FSM::Adapter::ISF;
use FSM::Scheduler::ISF;
use FSM::Support::ISFPublicInterfaceContract qw(
    build_isf_public_interface_contract
    isf_public_interface_schedule_report_multi_file_scope
    isf_public_interface_schedule_report_top_level_keys
);

subtest 'multi-file ISF report is parent-scoped with generated composition metadata' => sub {
    my $path = File::Spec->catfile($FindBin::Bin, '..', 'isf', 'spawn_parent.isf');
    my $actor = FSM::Adapter::ISF->new()->parse_file($path);
    my $scheduler = FSM::Scheduler::ISF->new();

    my $lowered = $scheduler->lower($actor);
    is_deeply(
        sorted([keys %{$lowered->{files}}]),
        [qw(child_worker.fsm spawn_parent.fsm spawn_parent_top.fsm)],
        'fixture still lowers to parent, child, and generated top files',
    );

    my $report = JSON::PP->new->decode($scheduler->report($actor));
    is_deeply(
        sorted([keys %$report]),
        sorted(isf_public_interface_schedule_report_top_level_keys()),
        'multi-file schedule report keeps the advertised top-level keys',
    );
    is($report->{source}, 'spawn_parent.isf', 'report source is the parent actor');
    is($report->{scheduled_fsm}, 'spawn_parent.fsm', 'report scheduled_fsm is the parent module');
    is_deeply(
        [map { $_->{name} } @{$report->{transactions}}],
        [qw(parent_main)],
        'report transaction summary is parent-scoped',
    );
    # Read the fixed parent's output-table declarations independently of JSON.
    my @parent_dt_names = $lowered->{files}{'spawn_parent.fsm'} =~ /^\s*\(-([^\s()]+)/mg;
    is_deeply(
        sorted([map { $_->{name} } @{$report->{dt_blocks}}]),
        sorted(\@parent_dt_names),
        'report DT summary contains exactly the parent scheduled-FSM tables',
    );
    is_deeply(
        [map { $_->{name} } grep { $_->{kind} eq 'drive' } @{$report->{dt_blocks}}],
        [qw(rdata)],
        'report retains the authored parent drive table',
    );
    is(scalar(grep { $_->{kind} eq 'child_completion' } @{$report->{dt_blocks}}), 3,
        'report retains completion tables for all three generated child joins');
    is($report->{generated_composition}{kind}, 'spawn_generated_top', 'report exposes generated composition kind');
    is($report->{generated_composition}{top_module}, 'spawn_parent_top', 'report exposes generated top module');
    is($report->{generated_composition}{top_fsm}, 'spawn_parent_top.fsm', 'report exposes generated top file');
    is_deeply(
        $report->{generated_composition}{parent},
        { module => 'spawn_parent', scheduled_fsm => 'spawn_parent.fsm' },
        'report exposes parent composition summary',
    );
    is_deeply(
        [map { $_->{instance} } @{$report->{generated_composition}{instances}}],
        [qw(w0 w1 w2)],
        'report exposes spawned instance summaries',
    );

    my $cli_report = run_schedule_json($path);
    is_deeply(
        $cli_report->{generated_composition},
        $report->{generated_composition},
        'CLI multi-file schedule report exposes the same generated composition metadata',
    );

    my $contract = build_isf_public_interface_contract();
    is(
        $contract->{schedule_report_multi_file_scope},
        isf_public_interface_schedule_report_multi_file_scope(),
        'contract advertises the current multi-file schedule-report scope',
    );
};

done_testing();

sub sorted {
    my ($values) = @_;
    return [sort @{$values || []}];
}

sub run_schedule_json {
    my ($path) = @_;
    my ($success, $error_message, $full_buf, $stdout_buf, $stderr_buf) = run(
        command => ['./bin/fsmgen', '--emit-schedule-json', $path],
    );

    ok($success, '--emit-schedule-json succeeds for the multi-file fixture');
    is(join('', @{$stderr_buf || []}), '', '--emit-schedule-json keeps stderr clean');

    return JSON::PP->new->decode(join('', @{$stdout_buf || []}));
}
